import { createClient, isQuoteFresh, OrderStatus, Partners, type Order, type SpotClient, type SwapQuote } from "@orbs-network/spot-ui";
import BN from "bignumber.js";
import { createPublicClient, createWalletClient, custom, erc20Abi, http, parseAbi, type Address, type EIP1193Provider, type Hash } from "viem";
import * as chains from "viem/chains";

const isNativeAddress = (address: string) =>
  address.toLowerCase() === "0x0000000000000000000000000000000000000000"
  || address.toLowerCase() === "0xeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee";

const chainId = 137;
const chain = Object.values(chains).find((value) => value.id === chainId);
if (!chain) throw new Error("Unsupported chain");
// Use the same partner for quoting and submission. Select your configured partner here.
const partner = "external" as Partners;
const provider = (window as Window & { ethereum?: EIP1193Provider }).ethereum;
if (!provider) throw new Error("A browser wallet is required");
const publicClient = createPublicClient({ chain, transport: http() });
const walletClient = createWalletClient({ chain, transport: custom(provider) });
let clientPromise: Promise<SpotClient> | undefined;
function getClient() {
  clientPromise ??= createClient(partner, chainId).catch((error) => {
    clientPromise = undefined;
    throw error;
  });
  return clientPromise;
}
let busy = false;

export type SwapInput = {
  quote: SwapQuote; // Display quote.minimumAmountOut unchanged in host review.
  sourceToken: Address;
  wrappedNativeTokenAddress: Address; // Chain configuration, never taken from an untrusted quote.
  signal?: AbortSignal; // Abort on unmount, account/chain change, or cancellation.
  pauseQuotes(): Promise<void>; // Pause polling and cancel in-flight quote requests.
  resumeQuotes(): void;
  // Hosts must ask for explicit review when a refreshed quote is worse.
  // Return true only after the user accepts the next quote and its minimum.
  reviewChangedQuote(previous: SwapQuote, next: SwapQuote): Promise<boolean>;
};

export async function swapFlow(account: Address, input: SwapInput) {
  if (busy) throw new Error("A swap is already being submitted");
  busy = true; // Retain the lock through settlement, including wallet prompts.
  try {
    await input.pauseQuotes();
    const client = await getClient();
    let quote = input.quote;
    const request = quote.request;
    async function assertContext() {
      input.signal?.throwIfAborted();
      const [addresses, chainId] = await Promise.all([walletClient.getAddresses(), walletClient.getChainId()]);
      input.signal?.throwIfAborted();
      if (chainId !== request.chainId || addresses[0]?.toLowerCase() !== account.toLowerCase()) {
        throw new Error("Wallet changed. Review the swap again.");
      }
    }
    await assertContext();
    // The connected signer is explicit, including for a disconnected preview quote.
    // Validate the signer, chain, partner, token pair, and quote minimum before wallet actions.
    if (request.chainId !== client.chainId || request.partner !== client.partner
        || !/^\d+$/.test(quote.netAmountOut) || !/^\d+$/.test(quote.minimumAmountOut)
        || BigInt(quote.minimumAmountOut) <= BigInt(0) || BigInt(quote.minimumAmountOut) > BigInt(quote.netAmountOut)) {
      throw new Error("Quote does not match the selected Spot configuration");
    }
    const token = request.inToken as Address;
    const amount = BigInt(request.inAmount);
    const nativeInput = isNativeAddress(input.sourceToken);
    if ((nativeInput ? input.wrappedNativeTokenAddress : input.sourceToken).toLowerCase() !== token.toLowerCase()) {
      throw new Error("Quote input does not match the selected token or configured wrapped native token");
    }
    function assertQuoteValue(quote: SwapQuote) {
      // Product minimum uses the service's quoted input value, without a separate price request.
      const valueUsd = BN(quote.inputAmountUsd ?? "");
      if (!valueUsd.isFinite() || valueUsd.lt(10)) throw new Error("A quote worth at least $10 with a USD value is required");
    }
    assertQuoteValue(quote);
    async function assertSpendBalance() {
      const balance = await publicClient.readContract({ address: token, abi: erc20Abi, functionName: "balanceOf", args: [account] });
      await assertContext();
      if (balance < amount) throw new Error("Insufficient input token balance");
    }
    if (nativeInput) {
      const balance = await publicClient.getBalance({ address: account });
      if (balance < amount) throw new Error("Insufficient native input balance");
      await assertContext();
      await wrapNativeToken(token, amount, account);
      // A retry must select the wrapped token or explicitly reuse this confirmed deposit.
    }
    await assertContext();
    await approveTokenIfNeeded(token, account, client.spenderAddress, amount, input.signal);
    await assertSpendBalance();
    await assertContext();
    if (!isQuoteFresh(quote, 20_000)) {
      const next = await client.getQuote({ ...request, user: account, signal: input.signal });
      await assertContext();
      const worse = BigInt(next.netAmountOut) < BigInt(quote.netAmountOut)
        || BigInt(next.minimumAmountOut) < BigInt(quote.minimumAmountOut);
      if (worse) {
        const accepted = await input.reviewChangedQuote(quote, next);
        if (!accepted) throw new Error("Updated quote was not accepted");
      }
      await assertContext();
      quote = next;
      // Keep the refreshed service minimum unchanged, including when it improves.
    }
    assertQuoteValue(quote);
    await assertSpendBalance();
    await assertContext();
    // Preparation can refresh quotes older than 20 seconds. Review any worse output.
    const prepared = await client.prepareSwap({ quote, account, signal: input.signal });
    await assertContext();
    if (BigInt(prepared.quote.netAmountOut) < BigInt(quote.netAmountOut)
        || BigInt(prepared.quote.minimumAmountOut) < BigInt(quote.minimumAmountOut)) {
      if (!await input.reviewChangedQuote(quote, prepared.quote)) throw new Error("Updated quote was not accepted");
      await assertContext();
    }
    quote = prepared.quote; // Freeze and display the exact quote selected for signing.
    assertQuoteValue(quote);
    // The SDK signs this service minimum unchanged with a three-minute expiration.
    const { signerAddress, typedData } = prepared.signingRequest;
    const signature = await walletClient.signTypedData({
      ...typedData,
      message: { ...typedData.message },
      account: signerAddress,
    });
    await assertSpendBalance();
    await assertContext();
    if (!isQuoteFresh(quote, 20_000)) throw new Error("Quote expired during signing. Review and sign again.");
    // Submission accepts an order; it does not confirm a fill.
    // Submit this exact prepared order and its original wallet signature only once.
    const order = await client.submitSwap(prepared.order, signature, { signal: input.signal });
    // Retain order.id for history/reconciliation if tracking stops or times out.
    const completed = await waitForSwap(client, order, input.signal);
    return completed;
  } finally {
    busy = false;
    input.resumeQuotes();
  }
}

const wrappedNativeAbi = parseAbi(["function deposit() payable"]);

async function waitForTransactionConfirmation(hash: Hash) {
  const receipt = await publicClient.waitForTransactionReceipt({ hash });
  if (receipt.status !== "success") throw new Error("Transaction reverted");
  return receipt;
}

async function hasEnoughAllowance(token: Address, account: Address, spender: Address, amount: bigint) {
  return await publicClient.readContract({
    address: token, abi: erc20Abi, functionName: "allowance", args: [account, spender],
  }) >= amount;
}

async function wrapNativeToken(token: Address, amount: bigint, account: Address) {
  const hash = await walletClient.writeContract({
    address: token, abi: wrappedNativeAbi, functionName: "deposit",
    value: amount, account, chain,
  });
  return waitForTransactionConfirmation(hash);
}

async function approveTokenIfNeeded(token: Address, account: Address, spender: Address, amount: bigint, signal?: AbortSignal) {
  if (await hasEnoughAllowance(token, account, spender, amount)) return;
  signal?.throwIfAborted();
  const hash = await walletClient.writeContract({
    address: token, abi: erc20Abi, functionName: "approve",
    args: [spender, amount], account, chain,
  });
  await waitForTransactionConfirmation(hash);
  for (let attempt = 0; attempt < 3; attempt += 1) {
    signal?.throwIfAborted();
    if (await hasEnoughAllowance(token, account, spender, amount)) return;
    if (attempt < 2) await new Promise((resolve) => setTimeout(resolve, 1_000));
  }
  throw new Error("Approval is not available. Check allowance before retrying.");
}

async function waitForSwap(client: SpotClient, accepted: Order, signal?: AbortSignal): Promise<Order> {
  // Keep the accepted identity; a timeout or stopped poll does not prove failure.
  const deadline = accepted.deadline + 60_000;
  if (!Number.isFinite(deadline) || accepted.deadline <= 0) throw new Error("Missing swap deadline; check order history");
  let latest = accepted;
  while (Date.now() < deadline) {
    signal?.throwIfAborted();
    if (latest.status === OrderStatus.Completed) return latest;
    if (latest.status === OrderStatus.Cancelled || latest.status === OrderStatus.Expired) {
      throw new Error("Swap " + latest.status.toLowerCase() + "; inspect history for partial fills");
    }
    const timeout = AbortSignal.timeout(Math.max(1, Math.min(10_000, deadline - Date.now())));
    const requestSignal = signal ? AbortSignal.any([signal, timeout]) : timeout;
    let current: Order | undefined;
    try {
      current = await client.getOrder({ orderId: accepted.id, signal: requestSignal });
    } catch {
      signal?.throwIfAborted(); // Retry status reads only; never repeat submission.
    }
    if (current && current.id === accepted.id && current.chainId === accepted.chainId) latest = current;
    if (latest.status !== OrderStatus.Open) continue;
    await new Promise<void>((resolve, reject) => {
      const finish = () => { signal?.removeEventListener("abort", abort); resolve(); };
      const timer = setTimeout(finish, Math.min(2_000, Math.max(0, deadline - Date.now())));
      const abort = () => { clearTimeout(timer); signal?.removeEventListener("abort", abort); reject(signal?.reason); };
      signal?.addEventListener("abort", abort, { once: true });
      if (signal?.aborted) abort();
    });
  }
  if (latest.status === OrderStatus.Completed) return latest;
  if (latest.status === OrderStatus.Cancelled || latest.status === OrderStatus.Expired) {
    throw new Error("Swap " + latest.status.toLowerCase() + "; inspect history for partial fills");
  }
  throw new Error("Swap settlement is unconfirmed. Check order history before retrying.");
}

